contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint minSum) public payable {
        require(address(this).balance >= amount);
        c.SetLogFile(address(0));
        c.SetMinSum(minSum);
        c.Deposit{value: amount}();
        uint recordedBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted
            && c.balances(address(this)) == recordedBefore - amount
            && address(c).balance == ethBefore - amount
            && address(this).balance >= amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
