        require(_val != _val2);
        c.SetMinSum(_val);
        uint before = c.MinSum();
        c.Initialized();
        bool reverted;
        try c.SetMinSum(_val2) { reverted = false; } catch { reverted = true; }
        uint after_ = c.MinSum();
        assert(reverted && after_ == before && before == _val);
    }
}

